window.RP_SESSION={"id":"S-1fa58aa2c089","messages":[{"id":"RP-II-0128933","time":"2026-07-30T02:14:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”왠지 모르게 모험심이 막 솟구친단 말이지!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128934","time":"2026-07-30T02:15:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"아! 그 느낌은 저 또한 잘 알고 있습니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128935","time":"2026-07-30T02:15:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그치!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128936","time":"2026-07-30T02:15:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 한밤중에 받을만한 의뢰는 없으려나~”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128937","time":"2026-07-30T02:15:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"밤이 되면 제, 사랑하는 여인(미정)께 나무 그늘 아래에서 직접 시를 쓴다거나, 혹은 저 나무 아래에서 별을 바라보는 일이로지요.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128938","time":"2026-07-30T02:16:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"저 별 하나 하나가 필히 저보다도 더욱 많은 모험담을 가지고 있는, 가히 살아있는 도서관이라 할 수 있으니. 저 별의 말을 듣고 있다 보면 결코 재미가 없을래야 없을수가 없었습니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128939","time":"2026-07-30T02:16:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"와인 드링킹!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128940","time":"2026-07-30T02:16:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128941","time":"2026-07-30T02:16:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 체력 판정 :\n[9] + [1] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0128942","time":"2026-07-30T02:16:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“오오, 감성적인걸요..”","characters":["P-5d58655d55ce"]},{"id":"RP-II-0128943","time":"2026-07-30T02:16:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"야호!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128944","time":"2026-07-30T02:17:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"자고로 별과 대화를 하는 것은 실로 감정적인 것이 맞으니. 예술가 조여, 그대는 예술가 답게 감성과 낭만의 분야를 잘 알고 있구나. 그러니 더더욱 낭만을 쫒아가도록 하게나.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128945","time":"2026-07-30T02:18:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"물론, 뻬르난떼는 자신이 정말로 별과 대화를 한다는 환청과 환각 증세에 불과했지만 말이다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128946","time":"2026-07-30T02:18:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“헹헹, 요즘도 밤에 너무 오래 깨있으면 그런 생각이 걷잡을 수 없이 많아져서.. 아, 슬슬 기절하러 가야겠다!”","characters":["P-5d58655d55ce"]},{"id":"RP-II-0128947","time":"2026-07-30T02:18:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“저도 이만 가보도록 하지요, 헹헹..”","characters":["P-5d58655d55ce"]},{"id":"RP-II-0128948","time":"2026-07-30T02:19:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"잘 가게나, 예술가 조여. 본디 제대로 됀 정신만이 캔버스에 화풍을 담아낼 수 있는 법이오니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128949","time":"2026-07-30T02:19:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“뻬르난떼 씨, 레마 씨도 늦게 주무시지 마시구요~”","characters":["P-5d58655d55ce"]},{"id":"RP-II-0128950","time":"2026-07-30T02:19:00+09:00","room":"RP II","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“허그도 너무 늦게 자지 마!”","characters":["P-5d58655d55ce"]},{"id":"RP-II-0128951","time":"2026-07-30T02:20:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 반말이다! 어쩐지 기쁜걸~”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128952","time":"2026-07-30T02:20:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“좋은 꿈 꿔, 조!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128953","time":"2026-07-30T02:21:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"공주님들은 언제 주무실 생각이옵니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128954","time":"2026-07-30T02:22:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어, 언젠간 잘거에요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128955","time":"2026-07-30T02:22:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 난 충분히 잔 거 같아서 말이지.\n정 잠이 안오면 의뢰라도 받아볼까 하고있다고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128956","time":"2026-07-30T02:22:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“보니까 야밤에 들어오는 의뢰는 몇 안되던데…”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128957","time":"2026-07-30T02:22:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“의뢰인들도 대부분 자고있더라.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128958","time":"2026-07-30T02:22:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"이 늦은 밤에 할 의뢰가 있지는 않는 것 같습니다. 그러니 저의 종자 맥도귈을 찾는 제 여정에 한번 발을 들여보심이 어떻습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128959","time":"2026-07-30T02:23:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어엥? 아 그, 이야기에서 들려주던?”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128960","time":"2026-07-30T02:24:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"맞습니다! 분명히 이리도 오랜 시간이 지났다면 저의 종자 맥도귈이 슬슬 저와 가까워 졌을 터! 본디 종자와 그 주군 되는 편력 기사는 보이지 않는 무언가로 인연이 이어졌나이니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128961","time":"2026-07-30T02:24:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"필히 둘이서 수색을 한다면 금방 찾을 수 있을 것이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128962","time":"2026-07-30T02:24:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 나야 좋지~ 마침 몸이 근질근질한 참이었다고!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128963","time":"2026-07-30T02:25:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그렇다면 저와 함께 밤의 밀회를 즐겨보도록 합시다!\"\n\n뻬르난떼는 자리에서 일어난 뒤, 모닥불에서 불타고 있는 장작 하나를 든 채로 길드의 밖으로 나와 도시 밖으로 향하려 하기 시작했다.\n\n\"이러니 마치 도시의 순찰을 돌고 있는 것 같군요. 그러나, 저의 숨는 능력이라면 필히 야간 순찰대에게 걸리지 않을 터.\"\n\n물론, 이는 근거 없는 뻬르난떼의 자신감이었다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128964","time":"2026-07-30T02:27:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이~!! 가보자고~”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128965","time":"2026-07-30T02:28:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"하지만 모험을 떠나겠다는 의욕도 잠시.\n\n\"? 어이! 이 늦은 밤에 웬 녀석들이야?\"\n\n곧바로 야간 순찰대에게 걸리고 말았다!\n\n둘 다 도적이 아니였던 탓에 쉽게 걸려버리고 만 것 같았다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128966","time":"2026-07-30T02:28:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…어엥?? 여이, 뭐야 벌써!!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128967","time":"2026-07-30T02:29:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“기사양반, 이렇게 된 이상 전속력으로 도주를…!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128968","time":"2026-07-30T02:29:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"공주님. 걱정하지 마시지요. 이럴때에는 아주 약간의 설득과 재치가 담겨져 있다면 결코 끌려가지 않을 터이니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128969","time":"2026-07-30T02:30:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…오? 여이, 진짜?”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128970","time":"2026-07-30T02:30:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"와인과 크래커 냠냠","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128971","time":"2026-07-30T02:31:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"여보게 병사여, 나는 그대가 생각하는 미천한 자가 아닌 귀족이며, 내 옆에 계신분은 그저 무장을 하셨을 뿐인 공주님이시니. 그저 밤의 여흥에 심취하여 이 도시 밖을 잠깐동안 나가며, 이 세상에 큰 일이 일어났는지, 혹은 모든것이 잘 돌아가고 있는지를 알기 위해 잠시 떠나는 것이로다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128972","time":"2026-07-30T02:31:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128973","time":"2026-07-30T02:31:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'돈 뻬르난떼 데 일리아'의 매력 판정 :\n[8] + [1] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0128974","time":"2026-07-30T02:31:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"페후히히","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128975","time":"2026-07-30T02:31:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"‘…여차할때 레마가 시킨거라고 하면 분명 무지막지한 미움을 받을거야, 여이, 참자 허그…‘","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128976","time":"2026-07-30T02:32:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"기사 나으리시라고요? 아 뭐... 음... 뭐, 공주님이랑 좋은 시간 보내십쇼! 키가 크시니까 충분히 만족시키시겄네요!\"\n\n다른 뜻으로 알아들은 평민이었지만, 아무튼 둘은 무사히 도시 밖으로 나갈 수 있었다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128977","time":"2026-07-30T02:32:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"와인을 잔뜩 마신 레마가 늘서진다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128978","time":"2026-07-30T02:32:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 외ㅡ, 와인, .. 헤헤.ㅇ.ㅇ. \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128979","time":"2026-07-30T02:32:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…여이, 레마를 저대로 두고 가는게 맞을려나…?“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128980","time":"2026-07-30T02:33:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"음... 위기에 처한 사람을 보고도 무시하는 것은 편력 기사의 도리가 아니오니.\"\n\n뻬르난떼는 레마를 부축 해 주려 하기 시작했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128981","time":"2026-07-30T02:34:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그도 옆에서 도와주려 했으나, 경과 키가 안맞네요.\n어쩔 수 없이 뒤에서 남은 음식들이나 들고 따라갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128982","time":"2026-07-30T02:34:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"부축받기","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128983","time":"2026-07-30T02:34:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"와인 좋아!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128984","time":"2026-07-30T02:34:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128985","time":"2026-07-30T02:34:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 체력 판정 :\n[8] + [1] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0128986","time":"2026-07-30T02:34:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"부축을 받으면서도 계속 병나발 불기.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128987","time":"2026-07-30T02:34:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 레마…! 나도 이정도로 술을 잘마시진 못하는데, 여이!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128988","time":"2026-07-30T02:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"와인!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128989","time":"2026-07-30T02:35:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“넌 티플링의 자존심이라고, 하하하~“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128990","time":"2026-07-30T02:35:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"뻬르난떼는 레마를 무사히 레마의 방까지 옮겨줬다!\n\n\"공주님. 거의 다 도착했습니다. 술은 필히 몸에 해로운 독극물이오니. 왠만해서는 마시지 않는 것을 종용하옵니다.\"\n\n물론 여성층이었기 때문에 다른 이들에겐 들키지 않겠금 살금 살금 움직인 현자 뻬르난떼였다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128991","time":"2026-07-30T02:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 히하하! 와인 최, 최고! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128992","time":"2026-07-30T02:36:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…나도 맥주 무지하게 들이키는 날엔 저랬었단 말이야…?“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128993","time":"2026-07-30T02:36:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 이거 캠프 사람들에게 미안해지는걸…“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128994","time":"2026-07-30T02:37:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"공주님도 저리 독극물을 섭취하시지만 않으면 되는 일이옵니다. 이리 깨달음을 쉽게 얻을 수 있었으니 좋은 일일 터.\"\n\n뻬르난떼는 길드의 층간에서 내려가기 시작했다.\n\n\"이제 저리도 취한 공주님을 다 옮겨줬으니 저희는 모험을 떠날 차례가 분명하옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0128995","time":"2026-07-30T02:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128996","time":"2026-07-30T02:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"취항ㄴ 레마","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128997","time":"2026-07-30T02:37:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"야호","characters":["P-fec1db60d51e"]},{"id":"RP-II-0128998","time":"2026-07-30T02:40:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…여이, 먹는거에 머리박고 자지만 않으면 되겠지 뭐~”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0128999","time":"2026-07-30T02:40:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"같이 내려갑니다~","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129000","time":"2026-07-30T02:41:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“근데 기사양반, 전부터 궁금했었는데 말이야!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129001","time":"2026-07-30T02:41:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"이후, 길드의 바깥, 그리고 이윽고 도시의 바깥까지 나온 뻬르난떼와 허그.\n\n당연히 새벽의 밤 답게 딱히 특별 한 일은 일어나지 않았다.\n\n가끔씩 귀뚜라미가 울거나, 사슴의 울음 소리가 들려오거나, 아님 누군가가 숲속에서 노숙을 하며 코고는 소리밖에 들려오지 않았다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129002","time":"2026-07-30T02:42:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“종자가 뭐하는거야?”\n\n평화로운 분위기 속에서 허그는 뻬르난떼에게 묻습니다. 어쩐지 중요한 질문일 것 같습니다!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129003","time":"2026-07-30T02:42:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"아! 공주님이 모르시는 것이 있다면 친히 대답을 해 드리는 것이 친절한 이웃 편력 기사이노니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129004","time":"2026-07-30T02:43:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"종자란 흔히들 기사의 제자 즈음 되는 자들을 일컫는 것이옵니다. 그들은 비록 평민인 탓에 기사는 됄 수 없으나, 사실상 기사에 가까운 종자는 됄 수 있나이니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129005","time":"2026-07-30T02:43:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 기사라는건 평민이면 못되는거였어?”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129006","time":"2026-07-30T02:43:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“너무하구만…”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129007","time":"2026-07-30T02:43:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그들은 갑옷 탓에 제대로 씻지도, 갑옷을 자력으로 벗지도 못하는 기사들을 위해 남들이 결코 하지 못할 일들을 해내며 제 주군을 위해 목숨 하나 바치는 영광스러운 자들을 말하는 것이외다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129008","time":"2026-07-30T02:44:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그렇습니다. 이는 만물의 아버지이자 어머니이신 라운데라께서 모든 존재들에게 숙명을 만든 탓이오니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129009","time":"2026-07-30T02:44:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“오오오! 기사 지킴이 막 그런건가?”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129010","time":"2026-07-30T02:44:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"본디 평민이라면 평민의 숙명이 있는 것이고, 귀족이라면 그러한 평민들을 지켜주고, 보호 해 주는 숙명이 있는 것이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129011","time":"2026-07-30T02:45:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”아무래도~ 나도 사냥꾼으로써의 숙명이 있지, 하하하!“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129012","time":"2026-07-30T02:45:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"허나, 기사는 자신의 종자를 지킬 의무가 있는 법이오니. 서로가 서로를 지켜주며, 서로의 버팀목이 되는 관계라 할 수 있지요.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129013","time":"2026-07-30T02:45:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그럼 기사양반에게도 그렇게 의지하던 상대가 있었다는거네?“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129014","time":"2026-07-30T02:45:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"물론이옵니다! 그리고 공주님께서는 공주의 숙명을 지니고 있으시니. 허나, 요즘의 매체들은 공주님들 또한 여러 직업을 가지며, 자유롭게 살기를 종용하는 바 이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129015","time":"2026-07-30T02:46:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"맞습니다. 저의 종자 맥도귈은 비록 전투를 꺼려하나, 저를 위해 그 무엇이던 제 몸을 아끼지 않는 멋진 자 이었습니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129016","time":"2026-07-30T02:47:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"이윽고, 호숫가에 도착 한 뻬르난떼는 호수의 수면 너머의 달빛을 바라보기 시작했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129017","time":"2026-07-30T02:47:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이… 그거 뭔가… 음……“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129018","time":"2026-07-30T02:47:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”……뭔가 아주 아주 중요한 녀석이었겠는걸.“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129019","time":"2026-07-30T02:48:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그렇습니다. 허나, 저의 머릿속에서는 제가 어찌 저의 소중 한 종자 맥도귈과 헤어지게 됐는지가 마치 안개와 같이 가려져서는 보이질 않으니.\"\n\n뻬르난떼는 호숫가를 손으로 휘저으며, 호수의 반사가 일어나지 않겠금 막았다.\n\n마치 안개와 같이 말이다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129020","time":"2026-07-30T02:49:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"이는 필히 저를 미워하고, 싫어하는 마법사 프레스턴이 저의 종자를 가로채기 위한 술수임이 분명하옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129021","time":"2026-07-30T02:49:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그 또한 비슷한 아이를 곁에 둔 적이 있었죠.\n…비록 그녀석은 먼저 떠나버렸으나, 경은 아직 이를 찾을 수 있고 그럴 희망을 품을 수 있네요.\n\n”…여이, 멋지구만, 기사양반은~“\n\n허그 또한 옆에서 손으로 물장구를 퉁퉁 해본다…","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129022","time":"2026-07-30T02:49:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”프레스턴… 또 나쁜 녀석이구만.“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129023","time":"2026-07-30T02:49:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"물론이옵니다. 자고로 멋진 자가 되는 방법중 하나는 포기하지 않는 마음이오니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129024","time":"2026-07-30T02:50:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“나쁜 녀석들은 참 이상하단 말이야.\n왜 그런 짓을 하는걸까? 누구 하나 좋아하질 않는데 말이야.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129025","time":"2026-07-30T02:50:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"어찌 소중 한 사람을 그렇게 쉽게 포기 할 수 있겠습니까? 비록 제가 저의 사랑하는 여인(미정)과 함께 하게 되더라도 저의 종자를 찾는 일을 포기하는 사태가 벌이지지 않게 됄 것이오니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129026","time":"2026-07-30T02:51:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"허나, 나쁜 자들은 본디 멋진 자와 착한 자들을 돋보이기 위한 역할이옵니다. 그 시련을 딛고 일어선다면 더욱 멋진 장면이 그려지지 않습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129027","time":"2026-07-30T02:51:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 확실히! 그렇긴 하네~”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129028","time":"2026-07-30T02:51:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그 때문에 우리는 맞서 싸워야만 하는 것이옵니다. 결코 포기하지도, 주저하지도 않으며, 용기있게, 또 명예롭게 앞서야만 하는 것이지요.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129029","time":"2026-07-30T02:51:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그래도 모두가 그런 고달픔을 넘겨낼 수 있는게 아니라는게 문제지.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129030","time":"2026-07-30T02:52:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“누군가는 그걸 그대로 받아들여 버려야만 할 수도 있고…”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129031","time":"2026-07-30T02:52:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어렵더라고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129032","time":"2026-07-30T02:52:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그런 자들을 위해서 우리가 있는 것 아니겠습니까? 우리와 같이 고난을 이겨낸 자들을 본다면 그들 또한 다시 용맹함을 되찾을 터.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129033","time":"2026-07-30T02:52:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"모범이 되고, 솔선 수범을 한다면 처음에는 꺼려 하더라도 한번이 두번이 되고, 두번이 세번이 되다 보면 이윽고 마음을 고쳐먹게 되는 것이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129034","time":"2026-07-30T02:53:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 기사양반의 생각은 말이야…”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129035","time":"2026-07-30T02:53:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“보면 볼수록 뭐랄까, 존경스럽다고 해야하나.”\n\n“말은 무지하게 많으면서도 뭐하나 나쁜말이 없단 말이지.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129036","time":"2026-07-30T02:54:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그것이 바로 편력 기사의 덕목이오니 말입니다. 그리도 무겁고, 중요 한 직위를 가졌음에도 한량과 같이 산다는 것은 결코 용납이 되지 않을 것이오니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129037","time":"2026-07-30T02:54:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"물론, 늘 올바른 말만 하는 것은 힘든 일이옵고, 저 또한 몇번 실수를 할 것이옵니다. 허나, 그 실수를 발판 삼아 다시 일어 설 때 마다 저는 더욱 단단 해 지고, 강력 해 지니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129038","time":"2026-07-30T02:55:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"저를 죽이지 못한 공격은 본디 저를 더욱 강하게 만드는 법이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129039","time":"2026-07-30T02:55:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이이이…… 멋지잖아 정말로.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129040","time":"2026-07-30T02:55:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"공주님도 이미 멋지신 분 아니십니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129041","time":"2026-07-30T02:56:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"저와 비슷하게 수 많은 고난과 시련이 있었음에도, 여성이라는 성별로, 공주라는 직위로 사냥꾼이라는 직업을 선택하셨나이니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129042","time":"2026-07-30T02:56:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"사람들의 차별을 한 몸에 받으심에도 불구하고 그리 서실 수 있으신 것은 이미 공주님께서 멋지신 분이시기 때문이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129043","time":"2026-07-30T02:56:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"아, 거기다가 종족 마저 다르시지요.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129044","time":"2026-07-30T02:57:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“차아아별이라 할걸 딱히 받진 않았지만 어렵긴 해, 사냥꾼이라는게.\n내가 그리 잘 아는것도 아니니 무진장 깨질때가 태반이고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129045","time":"2026-07-30T02:57:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“뭐, 아무튼간에!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129046","time":"2026-07-30T02:57:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그럼 둘 다 멋들어진 녀석으로 하자고, 여이!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129047","time":"2026-07-30T02:58:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"뻬르난떼의 어깨를 팔꿈치로 툭툭 칩니다.\n역시, 좋은 친구였네요~","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129048","time":"2026-07-30T02:58:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"물론이옵니다!\"\n\n뻬르난떼는 가방을 꺼낸 뒤, 수차례 쓰고, 지우기를 반복 한 종이를 꺼내기 시작했다.\n\n\"지금이라면 분명히 좋은 시가 나올 터!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129049","time":"2026-07-30T02:59:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"시를 쓰고 낭송 한다는 것은 문학적으로도, 정신적으로도 좋은 일이옵니다.\"\n\n물론, 자주 쓰는것과 잘 쓰는 것의 차이점은 존재 했었다.\n\n뻬르난떼는 필히 자주 쓰는 사람임이 분명 할 것이었다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129050","time":"2026-07-30T03:00:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 멋들어지게 한 번 써보자고 기사 양반!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129051","time":"2026-07-30T03:00:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"하지만 저에게는 시를 쓸때의 고난이 있습니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129052","time":"2026-07-30T03:00:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그것은 바로 본디, 편력 기사란 사랑하는 여인이 있어야 하는 법.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129053","time":"2026-07-30T03:01:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"저에게는 사랑하는 여인이 존재하지 않는 탓에 이름으로 인한 운율이 형성되지 않는다는 아주 큰 일이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129054","time":"2026-07-30T03:01:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음…… 그런가…“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129055","time":"2026-07-30T03:01:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"때문에 사랑하는 그녀를 생각하며 글을 쓰려 하려다가도 머릿속이 백지가 되어 더이상 글을 쓸 수가 없으니!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129056","time":"2026-07-30T03:01:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"이는 아직 제가 진정한 편력기사가 아니기 때문일 터.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129057","time":"2026-07-30T03:02:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그럼 말이야 기사 양반, 뭔가 그 여인이라는걸 주변에서 잠시 빌려오는건 어때?“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129058","time":"2026-07-30T03:02:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”어어, 말이 이상하긴 한데! 여이…“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129059","time":"2026-07-30T03:02:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그 뭐랄까…“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129060","time":"2026-07-30T03:03:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"아! 공주님께서 가히 천재적인 발상을 하셨군요! 덕분에 시를 쓸때 엄청 난 진전이 있을 것이옵니다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129061","time":"2026-07-30T03:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”호수! 지금 보면 호수가 이쁘잖아. 달도 이쁘고!“\n”기사 양반이 사랑하는 사람이라면 그쪽 눈에는 이쁘게 보일거 아냐. 그니까 이렇게 당장 눈에 보이는 이쁜것들을 그 여인이라는 것으로 두는거지!“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129062","time":"2026-07-30T03:04:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”예전에 알던 동료가 간간히 쓰던 방법인데, 녀석은 사냥꾼을 때려치고 바드가 되버렸지~“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129063","time":"2026-07-30T03:05:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그렇다면 공주님께서 말씀 하신대로 바로 해 보도록 하겠습니다. 허나, 호수는 살아있는 것의 이름이 아니오니. 공주님의 이름을 빌리도록 하겠나이다. '아, 나의 사랑하는 공주이신 가델랏이시여.'실로 뛰어난 이름의 운율을 지니고 계신 것이 시를 쓰기에 아주 좋습니다.\"\n\n뻬르난떼는 마치 어린아이와 같이 해맑게 기뻐했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129064","time":"2026-07-30T03:05:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음… 뭐… 그래~ 다들 허그라 부르니까 그정도야 뭐.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129065","time":"2026-07-30T03:07:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"공주님의 혜안 덕분에 더욱 더 문학적인 활동을 할 수 있게 됐습니다. 그러한 감사의 마음으로 기사들이라면 필히 하는, 손등에 입맞춤을 하도록 하겠나이다!\"\n\n뻬르난떼는 한쪽 무릎을 꿇은 뒤, 손을 뻗어 허그의 반응을 기다리기 시작했다.\n\n...키 차이 때문에 살짝 우스꽝스러운 모습이 됐지만 말이다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129066","time":"2026-07-30T03:07:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“감사하면 손등에 그런걸 받는거야? 특이하네 기사들은.”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129067","time":"2026-07-30T03:07:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“뭘 하면 되는거지? 내가 하면 되나?”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129068","time":"2026-07-30T03:08:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"저의 손에 손목을 포개주시면 되나이다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129069","time":"2026-07-30T03:08:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 뻬르난떼의 손에 손바닥이 위로 가도록 손을 냅다 던져두었다. 예잇!","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129070","time":"2026-07-30T03:10:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"뻬르난떼는 허그의 손등에 입맞춤을 했다.\n\n키차이 때문에 허그가 손을 좀 높이 올려야 했지만, 아무튼 책에서나 나오는 것을 해낸 뻬르난떼였다.\n\n\"오늘의 모험으로 이리도 가치 높은 것들을 얻었나이니. 새벽의 모험은 필히 얻을 것이 많은 모험이 분명 할 터. 허나, 안타깝게도 저의 종자인 맥도귈은 결코 발견 할 낌새 조차 보이지 않는군요.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129071","time":"2026-07-30T03:12:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“에이 뭐~ 어디던 막 돌아다니다 보면 나오겠지, 여이!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129072","time":"2026-07-30T03:12:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"새벽에는 본디 야생 동물들이 침범 할 수도 있는 법이오니. 이제 서둘러서 길드로 돌아가도록 해야 할 것 같습니다 공주님.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129073","time":"2026-07-30T03:12:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…그 종자라는 녀석, 반드시 찾아보자고.\n나도 힘이 닿는 한은 쭉 도와줄테니 말이야.\n식구의 식구는 내 식구기도 하고,\n난 내 식구가 하나라도 더 느는게 좋거든~”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129074","time":"2026-07-30T03:12:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 그래야겠구만!“","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129075","time":"2026-07-30T03:13:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"역시 호탕하신 분이옵니다. 감사합니다 공주님. 오늘의 은혜는 결코 잊지 않으리니!\"\n\n이후 뻬르난떼와 허그는 숲에서 도시로, 도시에서 길드 내부로 들어왔다.\n\n\"아! 실로 보람 찬 하루였습니다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129076","time":"2026-07-30T03:14:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 오늘 재미있었어! 별다른 수확은 없었는데…\n그럼 잘 자고!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129077","time":"2026-07-30T03:14:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아 참, 기사 양반. 기사 양반들을 좋게 부르는 말에는 뭐가 있어?”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129078","time":"2026-07-30T03:15:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"공주님도 잘 주무십시요! 아, 기사를 좋게 부르는 방식은.. 기사 나으리라는 말이 있겠으나 공주님은 귀족의 직위를 가지고 계시오니 이는 부적절 할 터. 경이라 부르시면 됩니다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129079","time":"2026-07-30T03:16:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"그러니까 예를 들어... 저의 이름인 뻬르난떼를 합쳐서 뻬르난떼 경이라는 말과 같이 하는 것이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129080","time":"2026-07-30T03:16:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음! 경이라, 짧고 좋네. 그럼 이따가 또 보자고, 뻬르난떼 경!”","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129081","time":"2026-07-30T03:17:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"\"알겠습니다 공주님!\"\n\n뻬르난떼는 이 말과 함께 허그에게 손 인사를 하며, 자신의 침소로 향하기 시작했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129082","time":"2026-07-30T03:17:00+09:00","room":"RP II","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그 또한 손을 흔들며 자신의 기숙사를 향해 발걸음을 옮깁니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-II-0129083","time":"2026-07-30T03:17:00+09:00","room":"RP II","name":"돈 뻬르난떼 데 일리아 / 야간 순찰대","profile":"돈 뻬르난떼 데 일리아","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-1a1afae9c8db"]},{"id":"RP-II-0129084","time":"2026-07-30T03:17:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
